<body>
<header class="header">
  <div class="header-inner">
    <div class="topbar">
      <div class="brand btn">Booking.com</div>
      <div class="account">
        <span class="currency">USD</span>
        <img class="flag-small btn" src="__PLACEHOLDER_ASSETS_BASE_DIR__/011.png" width="20" height="16" alt="United States">
        <span class="help btn">?</span>
        <button class="btn">Register</button>
        <button class="btn">Sign in</button>
      </div>
    </div>
    <nav class="nav">
      <a class="nav-item btn" href="#"><span class="nav-icon">▱</span>Stays</a>
      <a class="nav-item btn" href="#"><span class="nav-icon">✈</span>Flights</a>
      <a class="nav-item btn" href="#"><span class="nav-icon">♧</span>Flight + Hotel</a>
      <a class="nav-item btn" href="#"><span class="nav-icon">▰</span>Car rental</a>
      <a class="nav-item btn" href="#"><span class="nav-icon">♜</span>Cruises</a>
      <a class="nav-item active btn" href="#"><span class="nav-icon">♧</span>Activities</a>
      <a class="nav-item btn" href="#"><span class="nav-icon">▥</span>Airport taxis</a>
    </nav>
  </div>
</header>

<main class="main">
  <a class="back btn" href="#"><span class="back-arrow">‹</span><span>Ticket options</span></a>
  <div class="step">Step 1 of 2</div>
  <h1>General Admission to Universal Studios Hollywood</h1>
  <div class="warning"><span class="warning-icon">!</span>Your selected date is unavailable – choose another</div>
  <div class="hosted">This experience is hosted by a <a class="btn" href="#">business</a></div>

  <h2>Your details</h2>
  <a href="#" class="signin btn"><span class="user-symbol">♙</span>Sign in to use your saved details</a>

  <form class="form" id="bookingForm">
    <div class="row">
      <div class="field half" id="firstField">
        <label for="first">First Name <span class="required">*</span></label>
        <input class="btn" id="first" type="text" autocomplete="off">
      </div>
      <div class="field half" id="lastField">
        <label for="last">Last name <span class="required">*</span></label>
        <input class="btn" id="last" type="text" autocomplete="off">
      </div>
    </div>

    <div class="field full" id="emailField">
      <label for="email">Email Address <span class="required">*</span></label>
      <input class="btn" id="email" type="text" autocomplete="off">
      <div id="emailMessage"></div>
    </div>

    <div class="field full">
      <label for="phone">Phone (mobile number preferred) <span class="required">*</span></label>
      <div class="phone-row">
        <select class="country btn" aria-label="Country">
          <option>🇺🇸</option>
        </select>
        <input class="phone-input btn" id="phone" type="text" placeholder="+1" autocomplete="off">
      </div>
    </div>

    <div class="reservation">Reservation details</div>
    <div class="loader"></div>

    <div class="legal">
      <p>By clicking "Next: Payment details" and completing a booking, you agree with the <a class="btn" href="#">terms and conditions</a> of Booking.com and the privacy policy of Musement.</p>
      <p>Please see our Privacy Statement to understand how we use and protect your personal information.<br><a class="btn" href="#">Privacy Statement</a></p>
    </div>
  </form>

  <aside class="skeletons">
    <div class="skeleton"></div>
    <div class="skeleton"></div>
  </aside>
</main>

<script>
  const first = document.getElementById('first');
  const last = document.getElementById('last');
  const email = document.getElementById('email');
  const phone = document.getElementById('phone');
  const firstField = document.getElementById('firstField');
  const lastField = document.getElementById('lastField');
  const emailField = document.getElementById('emailField');
  const emailMessage = document.getElementById('emailMessage');

  function updateName(field, wrapper){
    wrapper.classList.toggle('valid', field.value.trim().length > 0);
  }
  first.addEventListener('input',()=>updateName(first,firstField));
  last.addEventListener('input',()=>updateName(last,lastField));

  email.addEventListener('input',()=>{
    emailField.classList.remove('invalid');
    emailMessage.className='helper';
    emailMessage.textContent = email.value ? "We'll send your confirmation details to " + email.value : "";
  });
  email.addEventListener('blur',()=>{
    if(email.value.trim() && !email.value.includes('@')){
      emailField.classList.add('invalid');
      emailMessage.className='error';
      emailMessage.textContent='Enter a valid email address';
    }
  });
</script>
</body>
</html>
